public class Main {
    public static void main(String[] args) {
        DnsCache cache = new DnsCache(300); // 300 second TTL

        System.out.println(cache.resolve("api.example.com", 0, "203.0.113.10"));
        System.out.println(cache.resolve("api.example.com", 100, "203.0.113.20"));
        System.out.println(cache.resolve("api.example.com", 280, "203.0.113.20"));
        System.out.println(cache.resolve("api.example.com", 310, "203.0.113.20"));
    }
}

// A DNS cache: an answer already cached and still within its TTL is served
// as-is, even if the real, authoritative answer has since changed, exactly
// the staleness risk a migration needs a lowered TTL to avoid.
class DnsCache {
    private final int ttlSeconds;
    private final Map<String, CachedAnswer> cache = new HashMap<>();

    DnsCache(int ttlSeconds) {
        this.ttlSeconds = ttlSeconds;
    }

    private static class CachedAnswer {
        String ip;
        long expiresAt;
        CachedAnswer(String ip, long expiresAt) {
            this.ip = ip;
            this.expiresAt = expiresAt;
        }
    }

    // currentAuthoritativeIp simulates what the real server's IP actually is right now,
    // which the cache only finds out about the next time it genuinely has to look it up.
    String resolve(String domain, long currentTime, String currentAuthoritativeIp) {
        CachedAnswer cached = cache.get(domain);
        if (cached != null && cached.expiresAt > currentTime) {
            return "t=" + currentTime + ": CACHE HIT, returning " + cached.ip;
        }
        cache.put(domain, new CachedAnswer(currentAuthoritativeIp, currentTime + ttlSeconds));
        return "t=" + currentTime + ": CACHE MISS, fresh lookup returned " + currentAuthoritativeIp;
    }
}

