#include <iostream>
#include <string>
#include <unordered_map>
using namespace std;

// A DNS cache: an answer already cached and still within its TTL is served
// as-is, even if the real, authoritative answer has since changed, exactly
// the staleness risk a migration needs a lowered TTL to avoid.
class DnsCache {
public:
    DnsCache(int ttlSeconds) : ttlSeconds(ttlSeconds) {}

    // currentAuthoritativeIp simulates what the real server's IP actually is right now,
    // which the cache only finds out about the next time it genuinely has to look it up.
    string resolve(const string& domain, long long currentTime, const string& currentAuthoritativeIp) {
        auto it = cache.find(domain);
        if (it != cache.end() && it->second.second > currentTime) {
            return "t=" + to_string(currentTime) + ": CACHE HIT, returning " + it->second.first;
        }

        cache[domain] = {currentAuthoritativeIp, currentTime + ttlSeconds};
        return "t=" + to_string(currentTime) + ": CACHE MISS, fresh lookup returned " + currentAuthoritativeIp;
    }

private:
    int ttlSeconds;
    unordered_map<string, pair<string, long long>> cache;
};

int main() {
    DnsCache cache(300); // 300 second TTL

    cout << cache.resolve("api.example.com", 0, "203.0.113.10") << endl;
    cout << cache.resolve("api.example.com", 100, "203.0.113.20") << endl;
    cout << cache.resolve("api.example.com", 280, "203.0.113.20") << endl;
    cout << cache.resolve("api.example.com", 310, "203.0.113.20") << endl;

    return 0;
}
